    28→
    29→const PIE_COLORS = [
    30→  '#1e3a5f', '#c8102e', '#d97706', '#0d6efd', '#198754',
    31→  '#6f42c1', '#fd7e14', '#20c997', '#0dcaf0', '#6c757d',
    32→  '#2c5282', '#e8a317', '#c70039', '#4361ee', '#2d6a4f',
    33→  '#9b59b6', '#e67e22', '#1abc9c', '#3498db', '#95a5a6',
