    59→  const barCardRef = useRef<HTMLDivElement>(null);
    60→  const pieCardRef = useRef<HTMLDivElement>(null);
    61→  const mapCardRef = useRef<HTMLDivElement>(null);
    62→  const pageRef = useRef<HTMLDivElement>(null);
    63→
    64→  const fetchStats = (f: string, t: string) => {
    65→    setLoading(true);
    66→    apiFetch(`/api/v1/reports/stats?from=${f}&to=${t}`)
    67→      .then((res) => setData(res))
    68→      .catch(() => setData(null))
    69→      .finally(() => setLoading(false));
    70→  };
    71→
    72→  useEffect(() => {
    73→    fetchStats(from, to);
    74→  }, []);
    75→
    76→  const applyRange = (f: string, t: string) => {
    77→    setFrom(f);
    78→    setTo(t);
