     1→import { useState, useEffect } from 'react';
     2→import { useParams, Link } from 'react-router-dom';
     3→import { apiFetch } from '../services/api';
     4→import { useAuth } from '../hooks/useAuth';
     5→import { EXERCISE_TYPES } from '../constants/exerciseTypes';
     6→
     7→const BUNDESLAENDER = [
     8→  { code: '01', name: 'Wien', label: 'OE1' },
     9→  { code: '02', name: 'Salzburg', label: 'OE2' },
    10→  { code: '03', name: 'Niederösterreich', label: 'OE3' },
    11→  { code: '04', name: 'Burgenland', label: 'OE4' },
    12→  { code: '05', name: 'Oberösterreich', label: 'OE5' },
    13→  { code: '06', name: 'Steiermark', label: 'OE6' },
    14→  { code: '07', name: 'Tirol', label: 'OE7' },
    15→  { code: '08', name: 'Kärnten', label: 'OE8' },
    16→  { code: '09', name: 'Vorarlberg', label: 'OE9' },
    17→];
    18→
    19→export default function ExerciseSetupPage() {
    20→  const { id } = useParams<{ id: string }>();
    21→  const { admin } = useAuth();
    22→  const isAdmin = admin?.role === 'admin';
    23→  const [exercise, setExercise] = useState<any>(null);
    24→  const [allRepeaters, setAllRepeaters] = useState<any[]>([]);
    25→  const [activeRepeaters, setActiveRepeaters] = useState<any[]>([]);
    26→  const [loading, setLoading] = useState(true);
    27→  const [activeBundeslaender, setActiveBundeslaender] = useState<Set<string>>(new Set());
    28→  const [expandedBl, setExpandedBl] = useState<Set<string>>(new Set());
    29→  const [showAddForm, setShowAddForm] = useState<string | null>(null); // bundesland_code or 'simplex'
    30→  const [newRepName, setNewRepName] = useState('');
    31→  const [newRepFreq, setNewRepFreq] = useState('');
    32→  const [newRepOffset, setNewRepOffset] = useState('');
    33→  const [newRepCtcss, setNewRepCtcss] = useState('');
    34→  const [newRepCallsign, setNewRepCallsign] = useState('');
    35→
    36→  useEffect(() => {
    37→    if (!id) return;
    38→    Promise.all([
    39→      apiFetch(`/api/v1/exercises/${id}`),
    40→      apiFetch('/api/v1/repeaters'),
    41→    ]).then(([ex, reps]) => {
    42→      setExercise(ex);
    43→      setAllRepeaters(reps);
    44→      setActiveRepeaters(ex.repeaters || []);
    45→      // Determine which Bundesländer have active repeaters
    46→      const activeBl = new Set<string>();
    47→      for (const er of (ex.repeaters || [])) {
    48→        const rep = reps.find((r: any) => r.id === er.repeater_id);
    49→        if (rep?.bundesland_code) activeBl.add(rep.bundesland_code);
    50→      }
    51→      setActiveBundeslaender(activeBl);
    52→      setExpandedBl(new Set(activeBl));
    53→    }).catch(() => {}).finally(() => setLoading(false));
    54→  }, [id]);
    55→
    56→  const repeatersForBl = (blCode: string) =>
    57→    allRepeaters.filter(r => r.bundesland_code === blCode && r.type !== 'simplex');
    58→
    59→  const simplexRepeaters = allRepeaters.filter(r => r.type === 'simplex');
    60→
    61→  const toggleBundesland = async (blCode: string) => {
    62→    const isActive = activeBundeslaender.has(blCode);
    63→    const newSet = new Set(activeBundeslaender);
    64→    const newExpanded = new Set(expandedBl);
    65→
    66→    if (isActive) {
    67→      // Deactivate all repeaters for this Bundesland
    68→      const blReps = repeatersForBl(blCode);
    69→      for (const rep of blReps) {
    70→        if (activeRepeaters.some(r => r.repeater_id === rep.id)) {
    71→          await apiFetch(`/api/v1/exercises/${id}/repeaters/${rep.id}`, { method: 'DELETE' });
    72→        }
    73→      }
    74→      newSet.delete(blCode);
    75→      newExpanded.delete(blCode);
    76→      setActiveRepeaters(prev => prev.filter(r => {
    77→        const rep = allRepeaters.find(ar => ar.id === r.repeater_id);
    78→        return rep?.bundesland_code !== blCode;
    79→      }));
    80→    } else {
    81→      newSet.add(blCode);
    82→      newExpanded.add(blCode);
    83→    }
    84→
    85→    setActiveBundeslaender(newSet);
    86→    setExpandedBl(newExpanded);
    87→  };
    88→
    89→  const toggleRepeater = async (repeaterId: number) => {
    90→    const isActive = activeRepeaters.some(r => r.repeater_id === repeaterId);
    91→    if (isActive) {
    92→      if (!isAdmin) return; // only admin can deactivate
    93→      await apiFetch(`/api/v1/exercises/${id}/repeaters/${repeaterId}`, { method: 'DELETE' });
    94→      setActiveRepeaters(prev => prev.filter(r => r.repeater_id !== repeaterId));
    95→    } else {
    96→      await apiFetch(`/api/v1/exercises/${id}/repeaters`, {
    97→        method: 'POST',
    98→        body: JSON.stringify({ repeater_id: repeaterId }),
    99→      });
   100→      const updated = await apiFetch(`/api/v1/exercises/${id}/repeaters`);
   101→      setActiveRepeaters(updated);
   102→    }
   103→  };
   104→
   105→  const addCustomRepeater = async (bundeslandCode: string | null) => {
   106→    if (!newRepName && !newRepFreq) return;
   107→    const type = bundeslandCode === null ? 'simplex' : 'repeater';
   108→    const name = newRepName || `Direkte ${newRepFreq}`;
   109→    const rep = await apiFetch('/api/v1/repeaters', {
   110→      method: 'POST',
   111→      body: JSON.stringify({
   112→        short_name: name,
   113→        frequency_mhz: newRepFreq ? parseFloat(newRepFreq) : null,
   114→        offset_mhz: newRepOffset ? parseFloat(newRepOffset) : null,
   115→        ctcss_hz: newRepCtcss ? parseFloat(newRepCtcss) : null,
   116→        callsign: newRepCallsign || null,
   117→        band: newRepFreq ? (parseFloat(newRepFreq) > 400 ? '70cm' : parseFloat(newRepFreq) > 200 ? '23cm' : '2m') : null,
   118→        type,
   119→        bundesland_code: bundeslandCode,
   120→      }),
   121→    });
   122→    setAllRepeaters(prev => [...prev, rep]);
   123→    // Auto-activate it
   124→    await apiFetch(`/api/v1/exercises/${id}/repeaters`, {
   125→      method: 'POST',
   126→      body: JSON.stringify({ repeater_id: rep.id }),
   127→    });
   128→    const updated = await apiFetch(`/api/v1/exercises/${id}/repeaters`);
   129→    setActiveRepeaters(updated);
   130→    setNewRepName('');
   131→    setNewRepFreq('');
   132→    setNewRepOffset('');
   133→    setNewRepCtcss('');
   134→    setNewRepCallsign('');
   135→    setShowAddForm(null);
   136→  };
   137→
   138→  const toggleExpanded = (blCode: string) => {
   139→    setExpandedBl(prev => {
   140→      const next = new Set(prev);
   141→      if (next.has(blCode)) next.delete(blCode);
   142→      else next.add(blCode);
   143→      return next;
   144→    });
   145→  };
   146→
   147→  if (loading) return <p className="text-gray-500">Laden...</p>;
   148→  if (!exercise) return <p className="text-red-500">Übung nicht gefunden</p>;
   149→
   150→  return (
   151→    <div className="space-y-6">
   152→      <div className="flex items-center justify-between gap-2">
   153→        <h1 className="text-base sm:text-xl font-bold text-[#1e3a5f] min-w-0">
   154→          <span className="block sm:inline">Übung einrichten</span>
   155→          <span className="hidden sm:inline"> — </span>
   156→          <span className="block sm:inline text-sm sm:text-xl">{new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT')}</span>
   157→        </h1>
   158→        <div className="flex gap-2 flex-shrink-0">
   159→          <Link to={`/exercises/${id}`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm">
   160→            Zurück
   161→          </Link>
   162→        </div>
   163→      </div>
   164→
   165→      {/* Exercise type + name (admin only) */}
   166→      {isAdmin && (
   167→        <div className="bg-white rounded-xl shadow p-3 sm:p-4">
   168→          <h2 className="text-base sm:text-lg font-semibold text-[#1e3a5f] mb-2 sm:mb-3">Typ & Name der Übung</h2>
   169→          <div className="flex flex-col sm:flex-row gap-3">
   170→            <div>
   171→              <label className="block text-xs text-gray-500 mb-1">Übungstyp</label>
   172→              <div className="flex gap-2">
   173→                <select
   174→                  value={EXERCISE_TYPES.some(t => t.value === (exercise.exercise_type || '')) ? exercise.exercise_type : '__custom__'}
   175→                  onChange={async (e) => {
   176→                    if (e.target.value === '__custom__') {
   177→                      setExercise((prev: any) => prev ? { ...prev, exercise_type: '' } : null);
   178→                    } else {
   179→                      await apiFetch(`/api/v1/exercises/${id}`, {
   180→                        method: 'PATCH',
   181→                        body: JSON.stringify({ exercise_type: e.target.value }),
   182→                      });
   183→                      setExercise((prev: any) => prev ? { ...prev, exercise_type: e.target.value } : null);
   184→                    }
   185→                  }}
   186→                  className="border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
   187→                >
   188→                  {EXERCISE_TYPES.map(t => (
   189→                    <option key={t.value} value={t.value}>{t.label}</option>
   190→                  ))}
   191→                  <option value="__custom__">Eigener Typ...</option>
   192→                </select>
   193→                {!EXERCISE_TYPES.some(t => t.value === (exercise.exercise_type || '')) && (
   194→                  <input
   195→                    type="text"
   196→                    value={exercise.exercise_type || ''}
   197→                    onChange={e => setExercise((prev: any) => prev ? { ...prev, exercise_type: e.target.value } : null)}
   198→                    onBlur={async (e) => {
   199→                      if (e.target.value) {
   200→                        await apiFetch(`/api/v1/exercises/${id}`, {
   201→                          method: 'PATCH',
   202→                          body: JSON.stringify({ exercise_type: e.target.value }),
   203→                        });
   204→                      }
   205→                    }}
   206→                    placeholder="Typ eingeben"
   207→                    className="border border-gray-300 rounded-lg px-3 py-2 text-sm flex-1 min-w-[140px] focus:outline-none focus:ring-2 focus:ring-blue-500"
   208→                    autoFocus
   209→                  />
   210→                )}
   211→              </div>
   212→            </div>
   213→            <div className="flex-1">
   214→              <label className="block text-xs text-gray-500 mb-1">Name (optional)</label>
   215→              <input
   216→                type="text"
   217→                defaultValue={exercise.name || ''}
   218→                placeholder="z.B. Sonntagsrunde KW 07"
   219→                onBlur={async (e) => {
   220→                  await apiFetch(`/api/v1/exercises/${id}`, {
   221→                    method: 'PATCH',
   222→                    body: JSON.stringify({ name: e.target.value || null }),
   223→                  });
   224→                }}
   225→                className="border border-gray-300 rounded-lg px-3 py-2 text-sm w-full max-w-md focus:outline-none focus:ring-2 focus:ring-blue-500"
   226→              />
   227→            </div>
   228→          </div>
   229→        </div>
   230→      )}
   231→
   232→      {/* OE-Link toggle (admin only) */}
   233→      {isAdmin && (
   234→        <div className="bg-white rounded-xl shadow p-3 sm:p-4">
   235→          <label className="flex items-center gap-3 cursor-pointer">
   236→            <input
   237→              type="checkbox"
   238→              checked={exercise.oe_link_enabled !== 0}
   239→              onChange={async (e) => {
   240→                const val = e.target.checked;
   241→                await apiFetch(`/api/v1/exercises/${id}`, {
   242→                  method: 'PATCH',
   243→                  body: JSON.stringify({ oe_link_enabled: val }),
   244→                });
   245→                setExercise((prev: any) => prev ? { ...prev, oe_link_enabled: val ? 1 : 0 } : null);
   246→              }}
   247→              className="w-5 h-5 accent-red-600"
   248→            />
   249→            <div>
   250→              <span className="font-semibold text-[#1e3a5f] text-sm sm:text-base">OE-Link aktivieren</span>
   251→              <p className="text-xs text-gray-500">OE-Link-Tab und Auswertung anzeigen (deaktivieren für Übungen ohne OE-Link, z.B. 80m Notfunk Runde)</p>
   252→            </div>
   253→          </label>
   254→        </div>
   255→      )}
   256→
   257→      {/* Bundesländer selection */}
   258→      <div className="bg-white rounded-xl shadow p-3 sm:p-4">
   259→        <h2 className="text-base sm:text-lg font-semibold text-[#1e3a5f] mb-2 sm:mb-3">Bundesländer auswählen</h2>
   260→        <div className="grid grid-cols-3 sm:grid-cols-5 lg:grid-cols-9 gap-2">
   261→          {BUNDESLAENDER.map(bl => {
   262→            const isActive = activeBundeslaender.has(bl.code);
   263→            const repCount = repeatersForBl(bl.code).length;
   264→            const activeCount = activeRepeaters.filter(ar => {
   265→              const rep = allRepeaters.find(r => r.id === ar.repeater_id);
   266→              return rep?.bundesland_code === bl.code;
   267→            }).length;
   268→            return (
   269→              <button
   270→                key={bl.code}
   271→                onClick={() => isAdmin && toggleBundesland(bl.code)}
   272→                disabled={!isAdmin}
   273→                className={`flex flex-col items-center py-2 px-1 rounded-lg border-2 transition-colors text-sm ${
   274→                  isActive
   275→                    ? 'border-red-500 bg-red-50 text-[#1e3a5f]'
   276→                    : 'border-gray-200 bg-gray-50 text-gray-500 hover:border-gray-300'
   277→                } ${!isAdmin ? 'cursor-default' : ''}`}
   278→              >
   279→                <span className="font-bold">{bl.label}</span>
   280→                <span className="text-xs truncate w-full text-center">{bl.name}</span>
   281→                {isActive && <span className="text-xs mt-0.5">{activeCount}/{repCount}</span>}
   282→              </button>
   283→            );
   284→          })}
   285→        </div>
   286→      </div>
   287→
   288→      {/* Per-Bundesland repeater sections */}
   289→      {BUNDESLAENDER.filter(bl => activeBundeslaender.has(bl.code)).map(bl => {
   290→        const blRepeaters = repeatersForBl(bl.code);
   291→        const isExpanded = expandedBl.has(bl.code);
   292→
   293→        return (
   294→          <div key={bl.code} className="bg-white rounded-xl shadow overflow-hidden">
   295→            <button
   296→              onClick={() => toggleExpanded(bl.code)}
   297→              className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors"
   298→            >
   299→              <div className="flex items-center gap-2">
   300→                <span className="font-bold text-[#1e3a5f]">{bl.label}</span>
   301→                <span className="font-semibold text-[#1e3a5f]">{bl.name}</span>
   302→                <span className="text-xs bg-red-100 text-red-800 px-2 py-0.5 rounded-full">
   303→                  {activeRepeaters.filter(ar => {
   304→                    const rep = allRepeaters.find(r => r.id === ar.repeater_id);
   305→                    return rep?.bundesland_code === bl.code;
   306→                  }).length} / {blRepeaters.length}
   307→                </span>
   308→              </div>
   309→              <span className="text-gray-400">{isExpanded ? '▲' : '▼'}</span>
   310→            </button>
   311→
   312→            {isExpanded && (
   313→              <div className="border-t px-4 pb-4">
   314→                <div className="space-y-1 mt-2">
   315→                  {blRepeaters.map(rep => {
   316→                    const active = activeRepeaters.find(r => r.repeater_id === rep.id);
   317→                    return (
   318→                      <div key={rep.id} className="flex items-center gap-3 py-2 border-b border-gray-100">
   319→                        <label className={`flex items-center gap-1.5 sm:gap-2 flex-1 flex-wrap ${!active || isAdmin ? 'cursor-pointer' : 'cursor-default'}`}>
   320→                          <input
   321→                            type="checkbox"
   322→                            checked={!!active}
   323→                            disabled={!!active && !isAdmin}
   324→                            onChange={() => toggleRepeater(rep.id)}
   325→                            className="w-4 h-4 accent-red-600 flex-shrink-0"
   326→                          />
   327→                          <span className="font-medium text-xs sm:text-sm">{rep.short_name}</span>
   328→                          <span className="text-xs text-gray-500 hidden sm:inline">
   329→                            {rep.frequency_mhz && `${rep.frequency_mhz} MHz`}
   330→                            {rep.callsign && ` (${rep.callsign})`}
   331→                          </span>
   332→                          {rep.ctcss_hz && <span className="text-xs text-gray-400 hidden md:inline">CTCSS {rep.ctcss_hz}</span>}
   333→                          {rep.is_linked ? <span className="text-xs bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded">oelink</span> : null}
   334→                          {rep.is_custom ? <span className="text-xs bg-purple-100 text-purple-700 px-1.5 py-0.5 rounded">custom</span> : null}
   335→                        </label>
   336→                      </div>
   337→                    );
   338→                  })}
   339→                </div>
   340→
