  } else {
    const adminHash = bcrypt.hashSync(adminPw, 10);
    const operatorHash = bcrypt.hashSync(operatorPw, 10);
    db.prepare('INSERT INTO admins (username, password_hash, role) VALUES (?, ?, ?)').run('bosarsa', adminHash, 'admin');
